function retroSlug($v){$v=iconv('UTF-8','ASCII//TRANSLIT',$v)?:$v;return trim(preg_replace('/[^a-z0-9]+/','-',strtolower($v)),'-');}
function retroLogoHtml($logo){$logo=(string)$logo;if(preg_match('~^/telesmart-img/oyunchu/retro_logos/[A-Za-z0-9._-]+$~',$logo)){return '<img src="'.ga_h($logo).'" alt="Loqo" style="width:90px;height:42px;object-fit:contain;background:#07111f;border-radius:6px;padding:4px">';}return '<span style="font-size:22px">'.ga_h($logo?:'🎮').'</span>'; }

function retroDeleteFileByUrl($u){
    global $romWeb,$coverWeb,$romRoot,$coverRoot,$baseFs;
    if(!$u) return;
    $path=null;
    if(str_starts_with($u,$romWeb.'/')) $path=$romRoot.'/'.ltrim(substr($u,strlen($romWeb.'/')),'/');
    elseif(str_starts_with($u,$coverWeb.'/')) $path=$coverRoot.'/'.ltrim(substr($u,strlen($coverWeb.'/')),'/');
    elseif(str_starts_with($u,'/games/oyunchu/')) $path=$baseFs.'/'.ltrim(substr($u,strlen('/games/oyunchu/')),'/');
    if($path && is_file($path)) @unlink($path);
}
function retroHttpJson($url){
    $ctx=stream_context_create(['http'=>['method'=>'GET','timeout'=>12,'header'=>"User-Agent: OyunchuRetro/1.0\\r\\nAccept: application/json\\r\\n"]]);
    $raw=@file_get_contents($url,false,$ctx);
    if($raw===false && function_exists('curl_init')){
        $ch=curl_init($url); curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>12,CURLOPT_USERAGENT=>'OyunchuRetro/1.0',CURLOPT_FOLLOWLOCATION=>true]); $raw=curl_exec($ch); curl_close($ch);
    }
    if(!$raw) return null; $j=json_decode($raw,true); return is_array($j)?$j:null;
}
function retroCleanGameTitle($name){
    $name=pathinfo($name,PATHINFO_FILENAME);
    $name=preg_replace('/\.(zip|7z|bin|md|gen|smd|nes|unf|unif|sfc|smc|gb|gbc|gba|iso|cue|img)$/i','',$name);
    // ROM dump region/version tags: (USA), [!] , [v1.1], Rev A, etc.
    $name=preg_replace('/\s*[\(\[][^\)\]]*(USA|EUR|Europe|Japan|JPN|World|Rev|v\d|!)[^\)\]]*[\)\]]/i','',$name);
    $name=preg_replace('/\s+(USA|EUR|Europe|Japan|JPN|World)\s*$/i','',$name);
    $name=preg_replace('/\s+v\d+(?:\.\d+)*\s*$/i','',$name);
    $name=preg_replace('/[_]+/',' ',$name);
    $name=preg_replace('/\s+/',' ',trim($name));
    return $name;
}
function retroDownloadImage($url,$target){
    $data=null;
    if(function_exists('curl_init')){ $ch=curl_init($url); curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_TIMEOUT=>15,CURLOPT_USERAGENT=>'OyunchuRetro/1.0']); $data=curl_exec($ch); curl_close($ch); }
    if(!$data) $data=@file_get_contents($url,false,stream_context_create(['http'=>['timeout'=>15,'header'=>"User-Agent: OyunchuRetro/1.0\r\n"]]));
    if(!$data || strlen($data)<1000) return false;
    return @file_put_contents($target,$data)!==false;
}
function retroAutoCover($title,$consoleSlug,$consoleName=''){
    global $coverRoot,$coverWeb;
    $clean=retroCleanGameTitle($title);
    $queries=array_values(array_unique(array_filter([
        trim($clean.' '.$consoleName.' video game'),
        trim($clean.' video game'),
        $clean
    ])));
    $thumb=null;
    foreach($queries as $q){
        $url='https://en.wikipedia.org/w/api.php?action=query&generator=search&gsrsearch='.rawurlencode($q).'&gsrnamespace=0&gsrlimit=10&prop=pageimages&piprop=thumbnail&pithumbsize=700&format=json';
        $j=retroHttpJson($url);
        foreach(($j['query']['pages']??[]) as $page){
            $pt=strtolower($page['title']??''); $t=$page['thumbnail']['source']??'';
            if(!$t) continue;
            $score=0;
            if(strtolower($clean)===$pt) $score+=100;
            if(stripos($pt,strtolower($clean))!==false) $score+=40;
            if($consoleName && stripos($pt,strtolower($consoleName))!==false) $score+=5;
            if(!$thumb || $score>$thumb['score']) $thumb=['url'=>$t,'score'=>$score];
        }
        if($thumb && $thumb['score']>=100) break;
    }
    // Wikimedia Commons fallback: useful when Wikipedia has no page image.
    if(!$thumb){
        $q=rawurlencode($clean.' game cover');
        $url='https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrsearch='. $q .'&gsrnamespace=6&gsrlimit=8&prop=imageinfo&iiprop=url&iiurlwidth=700&format=json';
        $j=retroHttpJson($url);
        foreach(($j['query']['pages']??[]) as $page){
            $ii=$page['imageinfo'][0]??[]; $t=$ii['thumburl']??($ii['url']??'');
            if($t){$thumb=['url'=>$t,'score'=>1];break;}
        }
    }
    if(!$thumb) return null;
    $source=$thumb['url']; $ext='jpg';
    if(preg_match('~\.(png|webp)(?:\?|$)~i',$source,$m)) $ext=strtolower($m[1]);
    $dir=$coverRoot.'/'.$consoleSlug; if(!is_dir($dir)) @mkdir($dir,0755,true); if(!is_dir($dir)||!is_writable($dir)) return null;
    $file=retroSlug($clean?:$title).'-auto-'.bin2hex(random_bytes(3)).'.'.$ext; $target=$dir.'/'.$file;
    if(!retroDownloadImage($source,$target)) return null;
    return $coverWeb.'/'.$consoleSlug.'/'.$file;
}
